-- Etapa 6C. Compra 2017; UF do pedido SP; todos os status. Executar READ ONLY.
WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , dominio AS (SELECT column1 status FROM (VALUES ('approved'),('canceled'),('created'),('delivered'),('invoiced'),('processing'),('shipped'),('unavailable')) s UNION SELECT order_status FROM p), a AS (SELECT order_status,count(DISTINCT order_id) pedidos FROM p GROUP BY order_status) SELECT d.status,coalesce(a.pedidos,0) pedidos,coalesce(a.pedidos,0)*100::numeric/nullif((SELECT count(DISTINCT order_id) FROM p),0) percentual,(SELECT count(DISTINCT order_id) FROM p) denominador FROM dominio d LEFT JOIN a ON a.order_status IS NOT DISTINCT FROM d.status ORDER BY d.status NULLS FIRST;
